from typing import List, Dict, Any, Union
from pypinyin import lazy_pinyin, Style
import ast
def _col_to_index_0based(col: Union[str, int],max_col: int) -> int:
    """将列索引转换为 0-based 的列索引
    :param col: 列索引（1-based 或字母表示）
    :param max_col: 最大列索引（用于验证,1-based）
    :return: 0-based 的列索引
    """
    if isinstance(col, str):
        # 先尝试将字符串转换为整数
        if not col.isalpha(): 
            col = int(col)
    if isinstance(col, int):
        # 验证列索引是否在有效范围内
        if col > max_col: raise ValueError(f"Column index must be <= {max_col}")
        if col==0: raise ValueError(f"Column index can't be 0")
        # 转换为 0-based 索引
        if col < 0:col=max_col+col
        else:col-=1
        return col
    elif isinstance(col, str):        
        col = col.upper().strip()
        idx = 0
        for ch in col:
            if not ch.isalpha(): raise ValueError(f"Invalid column letter: {col}")
            idx = idx * 26 + (ord(ch) - ord('A') + 1)
        return idx-1    
def sort_excel_data_by_column(
    data: Union[Dict[str, Any], str],
    sort_col: Union[str, int],
    sort_by_values: List[str] = None,    
    reverse: bool = False,
    has_header: bool = False
) -> Dict[str, Any]:
    """
    对数据按指定列排序。

    :param data: 二维列表，每个元素是包含 'value', 'style', 'abs_pos' 的字典
    :param start_col: 要排序的列标识（如 "A", "B", 1, 2 等）
    :param sort_by_values: 排序值集合，按该集合值的顺序固定排序（仅支持字符串匹配）
    :param reverse: 是否降序或反转，当 sort_by_values 非空时，对整个排序结果反转
    :param has_header: 首行是否为标题行（若为 True，则第1行为标题行，不参与排序，保持在最前）
    :return: 排序后的新数据（不修改原数据）
    """    
    if not data:
        return data
    # 安全解析输入（兼容字符串形式）
    if isinstance(data, str):
        data = ast.literal_eval(data)
    # 转换列标识为索引
    sort_col =  _col_to_index_0based(sort_col,len(data['data'][0]))
    if sort_col < -1 or sort_col >= len(data['data'][0]):
        raise IndexError("sort_col_index 超出列范围")
    # 分离标题行和数据行
    header = []
    rows_to_sort = data['data']
    if has_header:
        header = [data['data'][0]]          # 保留标题（作为列表的列表，便于后续拼接）
        rows_to_sort = data['data'][1:]
    if not rows_to_sort:
        return data  # 无数据可排序，直接返回
    # 构建自定义排序映射（仅当 sort_by_values 非空且非空列表）
    use_custom_order = bool(sort_by_values)
    if use_custom_order:
        # 转为字符串并去重保持顺序（可选）
        value_to_rank = {str(v): i for i, v in enumerate(sort_by_values)}
        max_rank = len(value_to_rank)

    def get_sort_key(row: List[Dict[str, Any]]) -> tuple:
        cell = row[sort_col]
        raw_value = cell['value']

        # 统一转为字符串用于比较（但保留原始类型用于 fallback）
        if raw_value is None:
            str_value = ""
        else:
            str_value = str(raw_value)

        if use_custom_order:
            # 自定义排序：先按 rank，再按拼音（用于同 rank 或未命中项）
            rank = value_to_rank.get(str_value, max_rank)
            # 为未命中项生成拼音 fallback，确保稳定排序
            if rank == max_rank:
                fallback = lazy_pinyin(str_value, style=Style.TONE3)
            else:
                fallback = []  # 已在自定义顺序中，无需额外排序
            return (rank, fallback)
        else:
            # 原始逻辑：拼音或原值
            if raw_value is None:
                return ("",)
            elif isinstance(raw_value, str):
                return lazy_pinyin(raw_value, style=Style.TONE3)
            else:
                return (raw_value,)

    # 执行排序
    sorted_rows = sorted(rows_to_sort, key=get_sort_key, reverse=reverse)
    data['data'] = header + sorted_rows
    return data

