def _build_condition(operator: str, value: Any) -> Callable[[Any], bool]:
    """
    根据操作符和值构建过滤条件函数。

    :param operator: 操作符，如 "==", "!=", "like", "is not None" 等
    :param value: 比较值（对 is None 类操作可忽略）
    :return: 接收 cell_value 并返回 bool 的函数
    """
    operator = operator.strip().lower()

    if operator == "is none":
        return lambda x: x is None and str(x).strip() == "" and str(x).strip().lower() == "none"

    if operator == "is not none":
        return lambda x: x is not None and str(x).strip() != "" and str(x).strip().lower() != "none"

    if operator == "==":
        return lambda x: x == value

    if operator == "!=":
        return lambda x: x != value

    if operator == ">":        
        # return lambda x: isinstance(x, (int, float)) and x > value
        return lambda x:float(x) > float(value)

    if operator == ">=":
        # return lambda x: isinstance(x, (int, float)) and x >= value
        return lambda x:float(x) >= float(value)

    if operator == "<":
        # return lambda x: isinstance(x, (int, float)) and x < value
        return lambda x:float(x) < float(value)

    if operator == "<=":
        # return lambda x: isinstance(x, (int, float)) and x <= value
        return lambda x:float(x) <= float(value)

    if operator == "in":
        value = ast.literal_eval(str(value))
        if not isinstance(value, (list, tuple, set)):
            raise ValueError("操作符 'in' 要求 value 是列表、元组或集合")
        val_set = set(value)
        return lambda x: x in val_set

    if operator == "not in":
        value = ast.literal_eval(str(value))
        if not isinstance(value, (list, tuple, set)):
            raise ValueError("操作符 'not in' 要求 value 是列表、元组或集合")
        val_set = set(value)
        return lambda x: x not in val_set

    if operator == "like":
        # 模糊匹配：转为字符串并检查是否包含（忽略大小写）
        pattern = str(value).lower() if value is not None else ""
        return lambda x: x is not None and pattern in str(x).lower()

    if operator == "startswith":
        prefix = str(value).lower() if value is not None else ""
        return lambda x: x is not None and str(x).lower().startswith(prefix)

    if operator == "endswith":
        suffix = str(value).lower() if value is not None else ""
        return lambda x: x is not None and str(x).lower().endswith(suffix)

    # 支持正则（可选扩展）
    if operator == "regex":
        try:
            compiled = re.compile(str(value), re.IGNORECASE)
        except re.error as e:
            raise ValueError(f"无效的正则表达式: {value}") from e
        return lambda x: x is not None and compiled.search(str(x)) is not None

    raise ValueError(f"不支持的操作符: '{operator}'")
def filter_excel_data_by_column(
    data: Dict[str, Any],
    filter_col: Union[str, int],
    operator: str,
    value: Any = None,
    has_header: bool = False
) -> List[List[Dict[str, Any]]]:
    """
    按操作符和值对指定列进行筛选。

    :param data:表格数据，包含 'data'（二维列表，每个元素为 {"value":"xx","abs_pos":[],"style_id":0}）和 'style_map'（样式ID到样式字典的映射）
    :param filter_col: 列（如 "B" 或 1）
    :param operator: 操作符，如 "like", "!=", "is not None" 等
    :param value: 比较值（对 is None 类可省略）
    :param has_header: 是否保留首行为标题
    """    
    # 分块处理逻辑
    if not data or not data.get('data') or not data['data'][0]:
        return data
    # 获取数据和样式映射
    excel_data = data['data']
    n_cols = len(excel_data[0])

    # 转换起始位置为 0-based
    col_index = _col_to_index_0based(filter_col, n_cols)    
    if col_index < 0 or col_index >= len(excel_data[0]):
        raise IndexError(f"列 {filter_col} 超出范围")

    condition = _build_condition(operator, value)

    if has_header:
        header = [excel_data[0]]
        rows_to_filter = excel_data[1:]
    else:
        header = []
        rows_to_filter = excel_data

    filtered_rows = [
        row for row in rows_to_filter
        if condition(row[col_index]['value'])
    ]
    data['data'] = header + filtered_rows
    return data

from typing import List, Dict, Any
def structure_custom_table_with_style_dynamic(
    data: Dict[str, Any],
) -> Dict[str, Any]:
    """
    结构化表格，支持：
      - 动态元信息列（WPO_SEG4 = ...）
      - GroupName 行识别（仅第一列有值）
      - 空行为分割标识，处理多个数据区域

    :param data:表格数据，包含 'data'（二维列表，每个元素为 {"value":"xx","abs_pos":[],"style_id":0}）和 'style_map'（样式ID到样式字典的映射）
    :return: 结构化表格，包含 'data'（二维列表，每个元素为 {"value":"xx","abs_pos":[],"style_id":0}）和 'style_map'（样式ID到样式字典的映射）
    """
    if not data or not data.get('data') or not data['data'][0]:
        return data

    # 获取数据
    excel_data = data['data']

    # 辅助函数：判断是否为全空行
    def is_empty_row(row):
        if not row:
            return True
        for cell in row:
            val = cell['value']
            if val is not None and str(val).strip() != "":
                return False
        return True

    # Step 1: 分割数据为多个区域（以连续空行为分隔）
    data_regions = []    
    current_region = []
    empty_row_count = 0

    for i, row in enumerate(excel_data):
        if is_empty_row(row):
            # 遇到空行，增加空行计数
            empty_row_count += 1
        else:
            # 遇到非空行
            if empty_row_count >= 2:
                # 连续空行（>=2），结束当前区域并开始新区域
                if current_region:
                    data_regions.append(current_region)
                    current_region = []
            # 重置空行计数
            empty_row_count = 0
            # 添加当前行到当前区域
            current_region.append(row)

    # 添加最后一个区域
    if current_region:
        data_regions.append(current_region)
    if not data_regions:
        return data

    # Step 2: 处理每个数据区域
    all_result_rows = []
    header_cells = None

    for region in data_regions:
        if not region or not region[0]:
            continue
        # 找标题行（第一个第二列非空）
        header_row_index = None
        for i, row in enumerate(region):
            if len(row) >= 2 and row[1]['value'] is not None and str(row[1]['value']).strip() != "":
                header_row_index = i
                break
        if header_row_index is None:
            continue  # 跳过无标题行的区域
        original_header_row = region[header_row_index]

        # 解析元信息行
        dynamic_meta = []
        for row in region[:header_row_index]:
            if not row or row[0]['value'] is None:
                continue
            s = str(row[0]['value']).strip()
            if "=" in s:
                key, val_part = s.split("=", 1)
                key = key.strip()
                value = val_part.split("\\")[0].strip()
                dynamic_meta.append((key, {
                    'value': value,
                    'style': row[0].get('style', {}),
                    'abs_pos': row[0].get('abs_pos', [0, 0])
                }))

        dynamic_keys = [k for k, _ in dynamic_meta]
        measure_columns = original_header_row[1:]

        # 构建表头（仅第一次构建）
        if header_cells is None:
            header_cells = []
            for key in dynamic_keys:
                header_cells.append({'value': key, 'style': {}, 'abs_pos': [0, len(header_cells)]})
            for col in ["GroupName", "RowName"]:
                header_cells.append({'value': col, 'style': {}, 'abs_pos': [0, len(header_cells)]})
            header_cells.extend(measure_columns)
        # 处理数据行
        current_group_name_cell = {'value': '', 'style': {}, 'abs_pos': [0, 0]}

        for row in region[header_row_index + 1:]:
            if not row:
                continue
            if is_empty_row(row):
                continue  # 跳过全空行

            # 判断是否为 GroupName 行：仅第一列有值，其余度量列为空
            is_group_row = True
            if len(row) <= 1:
                is_group_row = False
            else:
                for j in range(1, len(row)):
                    val = row[j]['value']
                    if val is not None and str(val).strip() != "":
                        is_group_row = False
                        break

            if is_group_row and len(row) > 0 and row[0]['value'] is not None and str(row[0]['value']).strip() != "":
                # 更新 GroupName
                current_group_name_cell = row[0]
            else:
                # 输出数据行
                new_row = []
                # 动态列
                for _, cell in dynamic_meta:
                    new_row.append(cell)
                # GroupName
                new_row.append(current_group_name_cell)
                # RowName
                row_name_cell = row[0] if len(row) > 0 else {'value': '', 'style': {}, 'abs_pos': [0, 0]}
                new_row.append(row_name_cell)
                # 度量列
                for j in range(1, len(original_header_row)):
                    if j < len(row):
                        new_row.append(row[j])
                    else:
                        new_row.append({
                            'value': None,
                            'style': {},
                            'abs_pos': [row_name_cell.get('abs_pos', [0, 0])[0], j]
                        })
                all_result_rows.append(new_row)

    # 构建最终结果
    if header_cells and all_result_rows:
        data['data'] = [header_cells] + all_result_rows

    return data

